export type FlagExposure = "public" | "server-only";

export type BooleanFlagDefinition = {
  type: "boolean";
  default: boolean;
  exposure: FlagExposure;
};

export type VariantFlagDefinition<T extends string = string> = {
  type: "variant";
  variants: readonly T[];
  default: T;
  exposure: FlagExposure;
};

export type FlagDefinition = BooleanFlagDefinition | VariantFlagDefinition;

export type FlagSchema = Record<string, FlagDefinition>;

export type FlagEvaluationContext = {
  userId?: string;
  attributes?: Record<string, string | number | boolean>;
};

export type FlagSnapshot = {
  schemaVersion: string;
  values: Record<string, boolean | string>;
  evaluatedAt?: string;
  identityKey?: string;
};

export type FlagFallbackReason =
  | "missing"
  | "invalid-type"
  | "disallowed-variant"
  | "malformed-snapshot"
  | "incompatible-snapshot"
  | "identity-changed";

export type FlagDiagnostic = {
  key: string;
  expected:
    { type: "boolean" } | { type: "variant"; variants: readonly string[] };
  reason: FlagFallbackReason;
  snapshotVersion?: string;
};

export type FlagAdapter = {
  evaluate: (input: {
    context?: FlagEvaluationContext;
    signal?: AbortSignal;
  }) => Promise<Record<string, unknown>> | Record<string, unknown>;
};

export type FlagRefreshResult =
  | { status: "updated"; snapshot: FlagSnapshot }
  | {
      status: "failed";
      reason: "invalid-snapshot" | "adapter-error" | "aborted";
    };

export type CreateFlagSnapshotInput = {
  schemaVersion: string;
  values: Record<string, unknown>;
  evaluatedAt?: string;
  identityKey?: string;
  includeServerOnly?: boolean;
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function expectedOf(definition: FlagDefinition): FlagDiagnostic["expected"] {
  if (definition.type === "boolean") {
    return { type: "boolean" };
  }
  return { type: "variant", variants: definition.variants };
}

function evaluateDefinition(
  definition: FlagDefinition,
  raw: unknown
): { value: boolean | string; reason?: FlagFallbackReason } {
  if (raw === undefined) {
    return { value: definition.default, reason: "missing" };
  }
  if (definition.type === "boolean") {
    if (typeof raw !== "boolean") {
      return { value: definition.default, reason: "invalid-type" };
    }
    return { value: raw };
  }
  if (typeof raw !== "string") {
    return { value: definition.default, reason: "invalid-type" };
  }
  if (!definition.variants.includes(raw)) {
    return { value: definition.default, reason: "disallowed-variant" };
  }
  return { value: raw };
}

export function identityKeyFromContext(
  context?: FlagEvaluationContext
): string | undefined {
  if (!context) {
    return undefined;
  }
  if (context.userId === undefined && context.attributes === undefined) {
    return undefined;
  }
  return JSON.stringify({
    userId: context.userId ?? null,
    attributes: context.attributes ?? {},
  });
}

export function createFlagSnapshot(
  schema: FlagSchema,
  input: CreateFlagSnapshotInput
): { snapshot: FlagSnapshot; diagnostics: FlagDiagnostic[] } {
  const diagnostics: FlagDiagnostic[] = [];
  const values: Record<string, boolean | string> = {};

  for (const [key, definition] of Object.entries(schema)) {
    if (definition.exposure === "server-only" && !input.includeServerOnly) {
      continue;
    }
    const evaluated = evaluateDefinition(definition, input.values[key]);
    values[key] = evaluated.value;
    if (evaluated.reason) {
      diagnostics.push({
        key,
        expected: expectedOf(definition),
        reason: evaluated.reason,
        snapshotVersion: input.schemaVersion,
      });
    }
  }

  const snapshot: FlagSnapshot = {
    schemaVersion: input.schemaVersion,
    values,
  };
  if (input.evaluatedAt !== undefined) {
    snapshot.evaluatedAt = input.evaluatedAt;
  }
  if (input.identityKey !== undefined) {
    snapshot.identityKey = input.identityKey;
  }

  return { snapshot, diagnostics };
}

export function resolveSnapshot(
  schema: FlagSchema,
  schemaVersion: string,
  snapshot: unknown,
  options?: { identityKey?: string; includeServerOnly?: boolean }
): { snapshot?: FlagSnapshot; diagnostics: FlagDiagnostic[] } {
  if (snapshot === undefined || snapshot === null) {
    return { diagnostics: [] };
  }
  if (!isRecord(snapshot) || typeof snapshot.schemaVersion !== "string") {
    return {
      diagnostics: [
        {
          key: "*",
          expected: { type: "boolean" },
          reason: "malformed-snapshot",
        },
      ],
    };
  }
  if (snapshot.schemaVersion !== schemaVersion) {
    return {
      diagnostics: [
        {
          key: "*",
          expected: { type: "boolean" },
          reason: "incompatible-snapshot",
          snapshotVersion: snapshot.schemaVersion,
        },
      ],
    };
  }
  const snapshotIdentity =
    typeof snapshot.identityKey === "string" ? snapshot.identityKey : undefined;
  if (
    snapshotIdentity !== options?.identityKey &&
    (snapshotIdentity !== undefined || options?.identityKey !== undefined)
  ) {
    return {
      diagnostics: [
        {
          key: "*",
          expected: { type: "boolean" },
          reason: "identity-changed",
          snapshotVersion: snapshot.schemaVersion,
        },
      ],
    };
  }

  const rawValues = isRecord(snapshot.values) ? snapshot.values : {};
  return createFlagSnapshot(schema, {
    schemaVersion,
    values: rawValues,
    evaluatedAt:
      typeof snapshot.evaluatedAt === "string"
        ? snapshot.evaluatedAt
        : undefined,
    identityKey: snapshotIdentity ?? options?.identityKey,
    includeServerOnly: options?.includeServerOnly,
  });
}

export function readFlagValue(
  schema: FlagSchema,
  snapshot: FlagSnapshot | undefined,
  key: string
): { value: boolean | string; diagnostic?: FlagDiagnostic } {
  const definition = schema[key];
  if (!definition) {
    throw new Error(`Unknown feature flag: ${key}`);
  }
  const evaluated = evaluateDefinition(definition, snapshot?.values[key]);
  return {
    value: evaluated.value,
    diagnostic: evaluated.reason
      ? {
          key,
          expected: expectedOf(definition),
          reason: evaluated.reason,
          snapshotVersion: snapshot?.schemaVersion,
        }
      : undefined,
  };
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import {
  createFlagSnapshot,
  identityKeyFromContext,
  readFlagValue,
  resolveSnapshot,
  type FlagAdapter,
  type FlagDiagnostic,
  type FlagEvaluationContext,
  type FlagRefreshResult,
  type FlagSchema,
  type FlagSnapshot,
} from "@/infra/feature-flags";

export class ServerOnlyFlagError extends Error {
  readonly name = "ServerOnlyFlagError";
  readonly key: string;

  constructor(key: string) {
    super(
      `Feature flag ${key} is server-only and cannot be read on the client`
    );
    this.key = key;
  }
}

export type FeatureFlagProviderProps = {
  schema: FlagSchema;
  schemaVersion: string;
  snapshot?: FlagSnapshot | null;
  adapter?: FlagAdapter;
  evaluationContext?: FlagEvaluationContext;
  refresh?: {
    intervalMs?: number;
    onWindowFocus?: boolean;
  };
  overrides?: Record<string, boolean | string>;
  sync?: {
    subscribe: (listener: (snapshot: FlagSnapshot) => void) => () => void;
    publish?: (snapshot: FlagSnapshot) => void;
  };
  onDiagnostic?: (diagnostic: FlagDiagnostic) => void;
  children: ReactNode;
};

type FlagContextValue = {
  schema: FlagSchema;
  schemaVersion: string;
  snapshot: FlagSnapshot | undefined;
  overrides?: Record<string, boolean | string>;
  refreshing: boolean;
  refresh: () => Promise<FlagRefreshResult>;
  onDiagnostic?: (diagnostic: FlagDiagnostic) => void;
};

const FlagContext = createContext<FlagContextValue | null>(null);

function emitDiagnostics(
  diagnostics: FlagDiagnostic[],
  onDiagnostic?: (diagnostic: FlagDiagnostic) => void
) {
  if (!onDiagnostic) {
    return;
  }
  for (const diagnostic of diagnostics) {
    onDiagnostic(diagnostic);
  }
}

export function FeatureFlagProvider({
  schema,
  schemaVersion,
  snapshot,
  adapter,
  evaluationContext,
  refresh: refreshConfig,
  overrides,
  sync,
  onDiagnostic,
  children,
}: FeatureFlagProviderProps) {
  const identityKey = identityKeyFromContext(evaluationContext);
  const baseline = useMemo(() => {
    const resolved = resolveSnapshot(schema, schemaVersion, snapshot, {
      identityKey,
    });
    return resolved;
  }, [schema, schemaVersion, snapshot, identityKey]);

  const [refreshed, setRefreshed] = useState<FlagSnapshot | undefined>(
    undefined
  );
  const [refreshing, setRefreshing] = useState(false);
  const [trackedIdentity, setTrackedIdentity] = useState(identityKey);
  const [trackedSnapshot, setTrackedSnapshot] = useState(snapshot);
  let nextRefreshed = refreshed;

  if (trackedIdentity !== identityKey || trackedSnapshot !== snapshot) {
    setTrackedIdentity(identityKey);
    setTrackedSnapshot(snapshot);
    nextRefreshed = undefined;
    setRefreshed(undefined);
  }

  const active = nextRefreshed ?? baseline.snapshot;
  const abortRef = useRef<AbortController | null>(null);
  const mountedRef = useRef(true);
  const onDiagnosticRef = useRef(onDiagnostic);

  useEffect(() => {
    onDiagnosticRef.current = onDiagnostic;
  }, [onDiagnostic]);

  useEffect(() => {
    emitDiagnostics(baseline.diagnostics, onDiagnosticRef.current);
  }, [baseline]);

  useEffect(() => {
    mountedRef.current = true;
    const controller = new AbortController();
    abortRef.current = controller;
    return () => {
      mountedRef.current = false;
      controller.abort();
    };
  }, []);

  const refresh = useCallback(async (): Promise<FlagRefreshResult> => {
    if (!adapter) {
      return { status: "failed", reason: "adapter-error" };
    }
    const controller = abortRef.current;
    const signal = controller?.signal;
    setRefreshing(true);
    try {
      const values = await adapter.evaluate({
        context: evaluationContext,
        signal,
      });
      if (signal?.aborted || !mountedRef.current) {
        return { status: "failed", reason: "aborted" };
      }
      if (
        typeof values !== "object" ||
        values === null ||
        Array.isArray(values)
      ) {
        return { status: "failed", reason: "invalid-snapshot" };
      }
      const next = createFlagSnapshot(schema, {
        schemaVersion,
        values,
        identityKey,
        evaluatedAt: new Date().toISOString(),
      });
      emitDiagnostics(next.diagnostics, onDiagnosticRef.current);
      setRefreshed(next.snapshot);
      sync?.publish?.(next.snapshot);
      return { status: "updated", snapshot: next.snapshot };
    } catch {
      if (signal?.aborted || !mountedRef.current) {
        return { status: "failed", reason: "aborted" };
      }
      return { status: "failed", reason: "adapter-error" };
    } finally {
      if (mountedRef.current) {
        setRefreshing(false);
      }
    }
  }, [adapter, evaluationContext, identityKey, schema, schemaVersion, sync]);

  useEffect(() => {
    if (!sync) {
      return;
    }
    return sync.subscribe((incoming) => {
      if (!mountedRef.current) {
        return;
      }
      const resolved = resolveSnapshot(schema, schemaVersion, incoming, {
        identityKey,
      });
      emitDiagnostics(resolved.diagnostics, onDiagnosticRef.current);
      if (resolved.snapshot) {
        setRefreshed(resolved.snapshot);
      }
    });
  }, [identityKey, schema, schemaVersion, sync]);

  useEffect(() => {
    if (!refreshConfig?.intervalMs || refreshConfig.intervalMs <= 0) {
      return;
    }
    const timer = window.setInterval(() => {
      void refresh();
    }, refreshConfig.intervalMs);
    return () => window.clearInterval(timer);
  }, [refresh, refreshConfig?.intervalMs]);

  useEffect(() => {
    if (!refreshConfig?.onWindowFocus) {
      return;
    }
    const onFocus = () => {
      void refresh();
    };
    window.addEventListener("focus", onFocus);
    return () => window.removeEventListener("focus", onFocus);
  }, [refresh, refreshConfig?.onWindowFocus]);

  const value = useMemo<FlagContextValue>(
    () => ({
      schema,
      schemaVersion,
      snapshot: active,
      overrides,
      refreshing,
      refresh,
      onDiagnostic,
    }),
    [
      active,
      onDiagnostic,
      overrides,
      refresh,
      refreshing,
      schema,
      schemaVersion,
    ]
  );

  return <FlagContext.Provider value={value}>{children}</FlagContext.Provider>;
}

function useFlagContext() {
  const context = useContext(FlagContext);
  if (!context) {
    throw new Error("useFlag must be used within FeatureFlagProvider");
  }
  return context;
}

function readPublicFlag(
  schema: FlagSchema,
  snapshot: FlagSnapshot | undefined,
  overrides: Record<string, boolean | string> | undefined,
  key: string
) {
  const definition = schema[key];
  if (definition?.exposure === "server-only") {
    throw new ServerOnlyFlagError(key);
  }
  if (overrides && Object.hasOwn(overrides, key)) {
    return readFlagValue(
      schema,
      {
        schemaVersion: snapshot?.schemaVersion ?? "",
        values: { [key]: overrides[key]! },
      },
      key
    );
  }
  return readFlagValue(schema, snapshot, key);
}

export function useFlag(key: string): boolean | string {
  const context = useFlagContext();
  const result = readPublicFlag(
    context.schema,
    context.snapshot,
    context.overrides,
    key
  );
  if (result.diagnostic) {
    context.onDiagnostic?.(result.diagnostic);
  }
  return result.value;
}

export function useFlags() {
  const context = useFlagContext();
  const flags: Record<string, boolean | string> = {};
  for (const [key, definition] of Object.entries(context.schema)) {
    if (definition.exposure === "server-only") {
      continue;
    }
    flags[key] = readPublicFlag(
      context.schema,
      context.snapshot,
      context.overrides,
      key
    ).value;
  }
  return {
    flags,
    snapshot: context.snapshot,
    refresh: context.refresh,
    refreshing: context.refreshing,
  };
}

import "server-only";

import {
  createFlagSnapshot,
  identityKeyFromContext,
  type FlagEvaluationContext,
  type FlagSchema,
  type FlagSnapshot,
} from "@/infra/feature-flags";

export type ServerFlagReadInput = {
  context?: FlagEvaluationContext;
  request?: unknown;
};

export type ServerFlagAdapter = {
  snapshot: (input?: {
    context?: FlagEvaluationContext;
    request?: unknown;
    includeServerOnly?: boolean;
    evaluatedAt?: string;
  }) => Promise<FlagSnapshot>;
};

export function createServerFlagAdapter(config: {
  schema: FlagSchema;
  schemaVersion: string;
  read: (
    input: ServerFlagReadInput
  ) => Promise<Record<string, unknown>> | Record<string, unknown>;
}): ServerFlagAdapter {
  return {
    async snapshot(input = {}) {
      const values = await config.read({
        context: input.context,
        request: input.request,
      });
      const { snapshot } = createFlagSnapshot(config.schema, {
        schemaVersion: config.schemaVersion,
        values,
        evaluatedAt: input.evaluatedAt,
        identityKey: identityKeyFromContext(input.context),
        includeServerOnly: input.includeServerOnly,
      });
      return snapshot;
    },
  };
}
